function useSettings(){const [settings,setSettings]=useState(defaultSettings);useEffect(()=>{getSiteSettings().then(setSettings)},[]);return settings}
function waLink(number, product='', code=''){const n=(number||defaultSettings.whatsapp_general).replace(/\D/g,'');const detail=product?`Tenho interesse em ${product}${code?` — código ${code}`:''}. Gostaria de saber valores, opções e prazo.`:'Gostaria de atendimento.';const msg=`Olá! ${detail} Vim pelo site da Home Interiores.`;return `https://wa.me/${n}?text=${encodeURIComponent(msg)}&utm_source=site&utm_medium=whatsapp`}
function normalizeText(v=''){return String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function isPromoActive(s){if(s.promo_enabled===false)return false;const now=Date.now(),a=s.promo_start_at?Date.parse(s.promo_start_at):0,b=s.promo_end_at?Date.parse(s.promo_end_at):0;return (!a||now>=a)&&(!b||now<=b)}
function productPath(p){return '/produto/'+(p.slug||`${slugify(p.name)}-${String(p.code||p.id).toLowerCase()}`)}
const COOKIE_KEY='home_interiores_cookie_consent_2026';
const RECENT_KEY='home_interiores_recentes_2026';
function readCookieConsent(){try{return JSON.parse(localStorage.getItem(COOKIE_KEY)||'null')}catch{return null}}
function notify(message,type='success'){try{window.dispatchEvent(new CustomEvent('home-toast',{detail:{message,type,id:Date.now()}}))}catch{}}
function trackEvent(name,params={}){try{const consent=readCookieConsent();if(!consent?.analytics)return;window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:name,...params})}catch{}}
function saveRecentProduct(id){try{const current=JSON.parse(localStorage.getItem(RECENT_KEY)||'[]');const next=[id,...(Array.isArray(current)?current:[]).filter(x=>x!==id)].slice(0,8);localStorage.setItem(RECENT_KEY,JSON.stringify(next));window.dispatchEvent(new Event('home-recent'))}catch{}}
function readRecentProducts(){try{const v=JSON.parse(localStorage.getItem(RECENT_KEY)||'[]');return Array.isArray(v)?v:[]}catch{return[]}}

function Seo({title='Home Interiores',description='Móveis, decoração e curadoria de interiores em Sete Lagoas.',image='',noindex=false}){const loc=useLocation();useEffect(()=>{try{const full=title.includes('Home Interiores')?title:`${title} | Home Interiores`;document.title=full;const set=(sel,attrs)=>{let el=document.head.querySelector(sel);if(!el){el=document.createElement('meta');Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));document.head.appendChild(el)}else Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));};set('meta[name="description"]',{name:'description',content:description});set('meta[property="og:title"]',{property:'og:title',content:full});set('meta[property="og:description"]',{property:'og:description',content:description});set('meta[property="og:type"]',{property:'og:type',content:'website'});set('meta[property="og:url"]',{property:'og:url',content:window.location.href});if(image)set('meta[property="og:image"]',{property:'og:image',content:image});set('meta[name="twitter:card"]',{name:'twitter:card',content:'summary_large_image'});set('meta[name="robots"]',{name:'robots',content:noindex?'noindex,nofollow':'index,follow'});let c=document.head.querySelector('link[rel="canonical"]');if(!c){c=document.createElement('link');c.rel='canonical';document.head.appendChild(c)}c.href=window.location.origin+loc.pathname;}catch(err){console.warn('SEO metadata não aplicado:',err)}},[title,description,image,noindex,loc.pathname]);return null}
const FAV_KEY='home_interiores_favoritos_2026';
function useFavorites(){const read=()=>{try{const value=JSON.parse(localStorage.getItem(FAV_KEY)||'[]');return Array.isArray(value)?value:[]}catch{return[]}};const [ids,setIds]=useState(read);const persist=next=>{const safe=Array.isArray(next)?next:[];setIds(safe);try{localStorage.setItem(FAV_KEY,JSON.stringify(safe));window.dispatchEvent(new Event('home-favorites'))}catch{}};useEffect(()=>{const sync=()=>setIds(read());window.addEventListener('home-favorites',sync);return()=>window.removeEventListener('home-favorites',sync)},[]);return {ids,toggle:id=>persist(ids.includes(id)?ids.filter(x=>x!==id):[...ids,id]),has:id=>ids.includes(id),clear:()=>persist([])}}
