function BrandLogo({admin=false}){return <img className={admin?'brandLogo adminBrandLogo':'brandLogo'} src={LOGO} alt="Home Interiores"/>}
function productImages(product){const many=Array.isArray(product?.image_urls)?product.image_urls.filter(Boolean):[];const all=[product?.image_url,...many].filter(Boolean);return [...new Set(all.length?all:[seedProducts[0].image_url])]}

function inferCategory(name='', categories=[]){
 const text=name.toLowerCase();
 const rules=[
  [['sofá','sofa','chaise','retrátil','retratil'],['Sofás','Sofa']],
  [['poltrona','puff'],['Poltronas']],
  [['cadeira','banqueta'],['Cadeiras']],
  [['mesa','tampo'],['Mesas','Mesa']],
  [['aparador','buffet'],['Aparadores']],
  [['rack','painel'],['Racks','Painéis','Paineis']],
  [['cama','cabeceira','criado','mesa de cabeceira'],['Dormitório','Dormitorio','Quartos']],
  [['tapete'],['Tapetes']],
  [['quadro','vaso','espelho','luminária','luminaria','decor'],['Decoração','Decoracao']],
 ];
 for(const [keys,targets] of rules){
  if(keys.some(k=>text.includes(k))){
   const found=categories.find(c=>targets.some(t=>c.name.toLowerCase().includes(t.toLowerCase())));
   if(found) return found.name;
  }
 }
 return '';
}
function inferEnvironment(name='', category=''){
 const text=`${name} ${category}`.toLowerCase();
 if(/cama|cabeceira|criado|dormit|quarto/.test(text)) return 'Quarto';
 if(/mesa|cadeira|buffet|aparador|jantar/.test(text)) return 'Sala de jantar';
 if(/gourmet|banqueta|bar/.test(text)) return 'Área gourmet';
 if(/decor|quadro|vaso|espelho|lumin/.test(text)) return 'Decoração';
 if(/escrit|office/.test(text)) return 'Escritório';
 return 'Sala de estar';
}
function productEnvironment(product){return product?.environment||inferEnvironment(product?.name,product?.category)}
const ENVIRONMENTS=['Sala de estar','Sala de jantar','Quarto','Área gourmet','Decoração','Escritório'];

function smartProductDraft(name, categories, current){
 const clean=name.trim();
 const category=inferCategory(clean,categories)||current.category||categories[0]?.name||'';
 const cat=category.toLowerCase();
 const copy=cat.includes('sof')?'Conforto, proporção e acabamento pensados para salas contemporâneas.':cat.includes('mesa')?'Presença escultórica e acabamento refinado para composições elegantes.':cat.includes('cadeira')?'Design leve, conforto e acabamento versátil para diferentes composições.':cat.includes('poltrona')?'Uma peça de presença, criada para trazer conforto e personalidade ao ambiente.':cat.includes('decor')?'Detalhe de curadoria para finalizar o ambiente com identidade.':'Design contemporâneo, acabamento refinado e presença marcante.';
 const description=current.description?.trim()?current.description:`${clean||'Peça selecionada'}. ${copy}`;
 const environment=current.environment||inferEnvironment(clean,category);
 return {...current,name:clean,category,description,environment};
}

function ToastHub(){
 const [items,setItems]=useState([]);
 useEffect(()=>{const fn=e=>{const item=e.detail||{};setItems(v=>[...v.slice(-2),item]);setTimeout(()=>setItems(v=>v.filter(x=>x.id!==item.id)),3000)};window.addEventListener('home-toast',fn);return()=>window.removeEventListener('home-toast',fn)},[]);
 return <div className="toastHub" aria-live="polite">{items.map(x=><div className={`toast ${x.type||'success'}`} key={x.id}><Check size={15}/><span>{x.message}</span></div>)}</div>
}
function CookieConsent(){
 const [consent,setConsent]=useState(()=>readCookieConsent());const [open,setOpen]=useState(false);const [prefs,setPrefs]=useState(()=>consent||{essential:true,analytics:false,marketing:false});
 useEffect(()=>{const fn=()=>{const c=readCookieConsent();setPrefs(c||{essential:true,analytics:false,marketing:false});setOpen(true)};window.addEventListener('home-cookie-settings',fn);return()=>window.removeEventListener('home-cookie-settings',fn)},[]);
 const save=next=>{const data={essential:true,analytics:!!next.analytics,marketing:!!next.marketing,updated_at:new Date().toISOString()};try{localStorage.setItem(COOKIE_KEY,JSON.stringify(data))}catch{};setConsent(data);setPrefs(data);setOpen(false);notify('Preferências de privacidade salvas.')};
 if(consent&&!open)return null;
 if(open)return <div className="cookieBackdrop" onMouseDown={e=>{if(e.target===e.currentTarget&&consent)setOpen(false)}}><section className="cookiePreferences" role="dialog" aria-modal="true" aria-label="Preferências de cookies"><button className="cookieClose" onClick={()=>consent&&setOpen(false)} aria-label="Fechar"><X size={19}/></button><span className="eyebrow">Privacidade</span><h2>Preferências de cookies</h2><p>Escolha como o site pode usar dados no seu dispositivo. Cookies essenciais permanecem ativos para recursos básicos.</p><label className="cookieRow locked"><span><b>Essenciais</b><small>Favoritos, segurança e funcionamento do site.</small></span><input type="checkbox" checked readOnly/></label><label className="cookieRow"><span><b>Análise</b><small>Ajuda a entender quais páginas e produtos despertam mais interesse.</small></span><input type="checkbox" checked={!!prefs.analytics} onChange={e=>setPrefs({...prefs,analytics:e.target.checked})}/></label><label className="cookieRow"><span><b>Marketing</b><small>Prepara o site para campanhas e pixels de mídia, quando configurados.</small></span><input type="checkbox" checked={!!prefs.marketing} onChange={e=>setPrefs({...prefs,marketing:e.target.checked})}/></label><div className="cookieActions"><button className="btn outline" onClick={()=>save({analytics:false,marketing:false})}>Somente essenciais</button><button className="btn" onClick={()=>save(prefs)}>Salvar preferências</button></div></section></div>;
 return <aside className="cookieBanner"><div><span className="eyebrow">Sua privacidade</span><p>Usamos cookies essenciais e, com sua permissão, dados de análise para melhorar sua experiência.</p><button className="cookieTextButton" onClick={()=>setOpen(true)}>Ver preferências</button></div><div className="cookieBannerActions"><button className="btn outline" onClick={()=>save({analytics:false,marketing:false})}>Recusar não essenciais</button><button className="btn" onClick={()=>save({analytics:true,marketing:true})}>Aceitar</button></div></aside>
}
function RecentlyViewed({products,title='Vistos recentemente'}){
 const [ids,setIds]=useState(()=>readRecentProducts());useEffect(()=>{const fn=()=>setIds(readRecentProducts());window.addEventListener('home-recent',fn);return()=>window.removeEventListener('home-recent',fn)},[]);
 const items=ids.map(id=>products.find(p=>p.id===id)).filter(Boolean).filter(p=>p.published!==false).slice(0,4);if(!items.length)return null;
 return <section className="section recentlyViewed"><div className="sectionHead compactHead"><div><span className="eyebrow">Continue explorando</span><h2>{title}.</h2></div><Link to="/catalogo">Ver catálogo <ArrowRight size={15}/></Link></div><div className="productGrid">{items.map(p=><ProductCard key={`recent-${p.id}`} p={p}/>)}</div></section>
}
function PromoTicker({settings}){
 const items=(Array.isArray(settings.promo_messages)?settings.promo_messages:defaultSettings.promo_messages).map(x=>String(x||'').trim()).filter(Boolean).slice(0,5);
 if(!isPromoActive(settings)||!items.length)return null;
 const loop=[...items,...items];
 return <div className="promoTicker" aria-label="Ofertas Home Interiores"><div className="promoTickerTrack">{loop.map((text,i)=><span className="promoTickerItem" key={`${text}-${i}`}><b>{text}</b><i aria-hidden="true">•</i></span>)}</div></div>
}
function SearchOverlay({open,onClose}){const [products,setProducts]=useState([]),[q,setQ]=useState('');useEffect(()=>{if(open)listProducts().then(setProducts)},[open]);useEffect(()=>{if(!open)setQ('')},[open]);if(!open)return null;const nq=normalizeText(q);const found=products.filter(p=>p.published!==false&&(!nq||normalizeText(`${p.name} ${p.category} ${p.code}`).includes(nq))).slice(0,6);return <div className="searchOverlay" role="dialog" aria-modal="true"><button className="searchOverlayClose" onClick={onClose} aria-label="Fechar busca"><X/></button><div className="searchOverlayInner"><span className="eyebrow">Busca rápida</span><div className="searchOverlayField"><Search size={24}/><input autoFocus value={q} onChange={e=>setQ(e.target.value)} placeholder="O que você procura?"/></div><div className="searchOverlayResults">{q&&found.map(p=><Link to={productPath(p)} onClick={onClose} key={p.id}><img src={productImages(p)[0]} alt=""/><span><b>{p.name}</b><small>{p.category} · {p.code}</small></span><ArrowRight size={18}/></Link>)}{q&&!found.length&&<div className="searchOverlayEmpty">Nenhuma peça encontrada para “{q}”.</div>}{!q&&<p className="searchOverlayHint">Busque por nome, categoria ou código do produto.</p>}</div></div></div>}
function Header(){const settings=useSettings();const [open,setOpen]=useState(false),[searchOpen,setSearchOpen]=useState(false),[scrolled,setScrolled]=useState(false);const {ids}=useFavorites();useEffect(()=>{const fn=()=>setScrolled(window.scrollY>24);fn();window.addEventListener('scroll',fn,{passive:true});return()=>window.removeEventListener('scroll',fn)},[]);useEffect(()=>{document.body.classList.toggle('menuOpen',open||searchOpen);return()=>document.body.classList.remove('menuOpen')},[open,searchOpen]);return <><PromoTicker settings={settings}/><header className={`header ${scrolled?'scrolled':''}`}><Link className="brandLogoLink" to="/" onClick={()=>setOpen(false)}><BrandLogo/></Link><div className="headerMobileActions"><button className="headerSearchBtn" onClick={()=>setSearchOpen(true)} aria-label="Buscar"><Search size={19}/></button><button className="menuBtn" onClick={()=>setOpen(!open)} aria-label="Menu" aria-expanded={open}>{open?<X/>:<Menu/>}</button></div><nav className={open?'nav open':'nav'} onClick={()=>setOpen(false)}><NavLink to="/catalogo">Catálogo</NavLink><NavLink to="/sobre">A Home</NavLink><NavLink to="/contato">Contato</NavLink><button className="navSearchBtn" onClick={e=>{e.stopPropagation();setOpen(false);setSearchOpen(true)}} aria-label="Buscar produtos"><Search size={19}/></button><NavLink className="favoriteNav" to="/favoritos"><Heart size={18}/><span>Favoritos</span>{ids.length>0&&<b>{ids.length}</b>}</NavLink><a className="instagramIconLink" href={settings.instagram_url} target="_blank" rel="noreferrer" aria-label="Instagram"><Instagram size={19}/></a><a className="book headerWhatsapp" href={waLink(settings.whatsapp_general)} target="_blank" rel="noreferrer" aria-label="WhatsApp" onClick={()=>trackEvent('whatsapp_click',{position:'header'})}><WhatsAppIcon size={19}/><span>Atendimento</span></a></nav></header><SearchOverlay open={searchOpen} onClose={()=>setSearchOpen(false)}/></>}
