function ProductCard({p,onOpen}){
 const navigate=useNavigate();const images=productImages(p);const [active,setActive]=useState(0),[hovered,setHovered]=useState(false);const fav=useFavorites();
 useEffect(()=>{if(images.length<2||hovered)return;const delay=4200+(String(p.id||p.name).length%5)*350;const timer=setInterval(()=>setActive(i=>(i+1)%images.length),delay);return()=>clearInterval(timer)},[images.length,hovered,p.id,p.name]);useEffect(()=>{if(images.length<2)return;const img=new Image();img.src=images[(active+1)%images.length]},[active,images.join('|')]);
 const go=(dir,e)=>{e?.stopPropagation();setActive(i=>(i+dir+images.length)%images.length)};
 return <article className="productCard productCardInteractive reveal" onMouseEnter={()=>setHovered(true)} onMouseLeave={()=>setHovered(false)} onClick={()=>onOpen?onOpen(p):navigate(productPath(p))} role="button" tabIndex={0} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onOpen?onOpen(p):navigate(productPath(p))}}}>
  <div className="productImage dynamicProductImage">{images.map((url,i)=><img key={url+i} loading="lazy" decoding="async" className={`productCover ${i===active?'active':''}`} src={url} alt={i===active?p.name:''} onError={e=>{e.currentTarget.onerror=null;e.currentTarget.src=designFallback}}/>)}
   <div className="productBadges">{p.featured&&<span className="tag">Destaque</span>}{p.status&&p.status!=='Disponível'&&<span className="statusTag">{p.status}</span>}</div>{images.length>1&&<span className="photoCount">{active+1}/{images.length}</span>}
   <button className={`favoriteBtn ${fav.has(p.id)?'active':''}`} onClick={e=>{e.stopPropagation();fav.toggle(p.id);notify(fav.has(p.id)?'Produto removido dos favoritos.':'Produto salvo nos favoritos.');trackEvent('favorite_toggle',{product:p.code})}} aria-label="Favoritar"><Heart size={18} fill={fav.has(p.id)?'currentColor':'none'}/></button>
   {images.length>1&&<div className="cardGalleryControls"><button onClick={e=>go(-1,e)} aria-label="Foto anterior"><ChevronLeft size={17}/></button><button onClick={e=>go(1,e)} aria-label="Próxima foto"><ChevronRight size={17}/></button></div>}
   {images.length>1&&<div className="cardDots">{images.slice(0,6).map((_,i)=><button key={i} className={i===active?'active':''} onClick={e=>{e.stopPropagation();setActive(i)}} aria-label={`Foto ${i+1}`}/>)}</div>}
   <a className="productQuickWa" href={waLink(p.seller_whatsapp,p.name,p.code)} target="_blank" rel="noreferrer" aria-label={`WhatsApp sobre ${p.name}`} onClick={e=>{e.stopPropagation();trackEvent('whatsapp_product',{product:p.code})}}><WhatsAppIcon size={18}/></a>
  </div><div className="productBody"><div className="productLabels"><span className="eyebrow">{p.category||'Curadoria Home'}</span><small>{p.code}</small></div><h3>{p.name}</h3><div className="productMeta"><div className="priceStack">{p.old_price&&<del>{p.old_price}</del>}{p.price?<b className="price">{p.price}</b>:<span className="productOpenHint">Consultar valor</span>}</div><Link to={productPath(p)} onClick={e=>e.stopPropagation()} className="productOpenHint">Ver detalhes</Link></div></div>
 </article>
}
function ProductModal({product,onClose,products=[]}){
 const [active,setActive]=useState(0),[touchStart,setTouchStart]=useState(null);const images=productImages(product);
 useEffect(()=>{setActive(0)},[product?.id]);
 useEffect(()=>{if(!product)return;const prev=document.body.style.overflow;document.body.style.overflow='hidden';const key=e=>{if(e.key==='Escape')onClose();if(e.key==='ArrowRight')setActive(i=>(i+1)%images.length);if(e.key==='ArrowLeft')setActive(i=>(i-1+images.length)%images.length)};window.addEventListener('keydown',key);return()=>{document.body.style.overflow=prev;window.removeEventListener('keydown',key)}},[product,onClose,images.length]);
 if(!product)return null;
 const manual=Array.isArray(product.related_ids)?product.related_ids:[];const related=(manual.length?products.filter(x=>manual.includes(x.id)):products.filter(x=>x.id!==product.id&&x.category===product.category)).filter(x=>x.id!==product.id).slice(0,3);
 const swipeEnd=e=>{if(touchStart==null)return;const end=e.changedTouches?.[0]?.clientX??touchStart;const delta=end-touchStart;if(Math.abs(delta)>45)setActive(i=>(i+(delta<0?1:-1)+images.length)%images.length);setTouchStart(null)};
 return <div className="productModalBackdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="productModal premiumProductModal"><button className="productModalClose" onClick={onClose}><X size={21}/></button><div className="productModalGallery"><div className="productModalImage" onTouchStart={e=>setTouchStart(e.touches[0].clientX)} onTouchEnd={swipeEnd}><img src={images[active]} alt={`${product.name} - foto ${active+1}`} onError={e=>{e.currentTarget.onerror=null;e.currentTarget.src=designFallback}}/>{images.length>1&&<><button className="galleryArrow galleryPrev" onClick={()=>setActive(i=>(i-1+images.length)%images.length)}><ChevronLeft/></button><button className="galleryArrow galleryNext" onClick={()=>setActive(i=>(i+1)%images.length)}><ChevronRight/></button><span className="mobileSwipeHint">deslize para ver</span></>}</div>{images.length>1&&<div className="productThumbs">{images.map((url,i)=><button key={url+i} className={i===active?'active':''} onClick={()=>setActive(i)}><img src={url} alt=""/></button>)}</div>}</div><div className="productModalContent"><div className="modalLabels"><span className="eyebrow">{product.category}</span><span>{product.code} · {images.length} foto{images.length===1?'':'s'}</span></div><h2>{product.name}</h2><p>{product.description}</p>{product.old_price&&<del className="modalOldPrice">{product.old_price}</del>}{product.price&&<b className="productModalPrice">{product.price}</b>}<div className="modalUtility"><Link to={productPath(product)}>Abrir página <ExternalLink size={15}/></Link><button onClick={async()=>{const url=location.origin+productPath(product);if(navigator.share){await navigator.share({title:product.name,text:product.name,url}).catch(()=>{})}else{await navigator.clipboard?.writeText(url);notify('Link do produto copiado.')}}}><Share2 size={15}/> Compartilhar</button></div><div className="productModalBottom"><div><small>Atendimento</small><strong>{product.seller_name||'Equipe Home Interiores'}</strong></div><a className="productWaIcon productWaIconLarge" href={waLink(product.seller_whatsapp,product.name,product.code)} target="_blank" rel="noreferrer"><WhatsAppIcon size={23}/></a></div>{related.length>0&&<div className="relatedProducts"><span className="eyebrow">Combine com</span>{related.map(r=><article key={r.id}><img src={productImages(r)[0]} alt=""/><span>{r.name}</span></article>)}</div>}</div></section></div>
}

function SignatureFeature({products}){const p=products.find(x=>x.featured)||products[0];if(!p)return null;const images=productImages(p);return <section className="signatureFeature"><div className="signatureMedia"><img src={images[0]} alt={p.name}/>{images[1]&&<img className="signatureAlt" src={images[1]} alt=""/>}</div><div className="signatureCopy"><span className="eyebrow">Seleção Home</span><h2>{p.name}</h2><p>{p.description||'Uma peça escolhida para ambientes que valorizam design, proporção e acabamento.'}</p><div className="signatureActions"><Link to={`/catalogo?categoria=${encodeURIComponent(p.category||'')}`}>Explorar coleção <ArrowRight size={15}/></Link><a href={waLink(p.seller_whatsapp,p.name)} target="_blank" rel="noreferrer">Consultar <WhatsAppIcon size={15}/></a></div></div></section>}

function FeaturedProducts(){const [products,setProducts]=useState(seedProducts),[selected,setSelected]=useState(null);useEffect(()=>{listProducts().then(setProducts)},[]);const featured=products.filter(p=>p.featured).slice(0,6);return <><section className="section storefrontSection"><div className="sectionHead compactHead"><div><span className="eyebrow">Destaques</span><h2>Escolhas da Home.</h2></div><Btn to="/catalogo">Ver tudo</Btn></div><div className="productGrid">{(featured.length?featured:products.slice(0,6)).map(p=><ProductCard key={p.id} p={p} onOpen={setSelected}/>)}</div></section><ProductModal product={selected} products={products} onClose={()=>setSelected(null)}/></>}

function MovingShowcase({products}){
 const [selected,setSelected]=useState(null);
 const picks=(products.filter(p=>productImages(p).length>1).length?products.filter(p=>productImages(p).length>1):products).slice(0,8);
 if(!picks.length)return null;
 const rail=[...picks,...picks];
 return <><section className="movingShowcase"><div className="movingShowcaseHead"><div><span className="eyebrow">Vitrine em movimento</span><h2>Veja mais de perto.</h2></div><Link to="/catalogo">Abrir catálogo <ArrowRight size={15}/></Link></div><div className="movingViewport"><div className="movingRail">{rail.map((p,i)=><button className="movingTile" key={`${p.id}-${i}`} onClick={()=>setSelected(p)}><img src={productImages(p)[i%productImages(p).length]} alt={p.name}/><div><span>{p.category}</span><strong>{p.name}</strong><small>Ver detalhes</small></div></button>)}</div></div></section><ProductModal product={selected} products={products} onClose={()=>setSelected(null)}/></>
}

function Home(){const s=useSettings();const [products,setProducts]=useState(seedProducts);useEffect(()=>{listProducts().then(setProducts)},[]);const categories=[...new Set(products.map(p=>p.category).filter(Boolean))].slice(0,8);return <Shell><Seo title="Home Interiores | Móveis e decoração em Sete Lagoas" description="Curadoria de móveis e decoração de alto padrão em Sete Lagoas. Explore sofás, mesas, cadeiras, poltronas e peças selecionadas." image={s.og_image_url||s.hero_image_url}/><section className="hero homeHero commerceHero"><img src={s.hero_image_url} alt="Ambiente Home Interiores"/><div className="overlay"/><div className="heroContent"><span>{s.hero_kicker}</span><h1>{s.hero_title}</h1><p>{s.hero_subtitle}</p><div className="actions"><Btn to="/catalogo">Ver catálogo</Btn><a className="btn outline" href={waLink(s.whatsapp_general)} target="_blank" rel="noreferrer">WhatsApp <WhatsAppIcon size={16}/></a></div></div><div className="heroIndex"><span>HOME INTERIORES</span><span>SETE LAGOAS · MG</span></div></section><section className="categoryShowcase"><div className="categoryShowcaseTop"><span className="eyebrow">Categorias</span><Link to="/catalogo">Ver tudo <ArrowRight size={15}/></Link></div><div className="categoryScroller">{categories.map(cat=>{const p=products.find(x=>x.category===cat);return <Link className="categoryTile" key={cat} to={`/catalogo?categoria=${encodeURIComponent(cat)}`}><img src={productImages(p)[0]} alt=""/><span>{cat}</span></Link>})}</div></section><SignatureFeature products={products}/><MovingShowcase products={products}/><FeaturedProducts/><section className="section newArrivals"><div className="sectionHead compactHead"><div><span className="eyebrow">Novidades</span><h2>Recém-chegados.</h2></div><Link to="/catalogo">Ver catálogo <ArrowRight size={15}/></Link></div><div className="productGrid editorialProductGrid">{products.filter(p=>p.published!==false).slice().sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0)).slice(0,3).map(p=><ProductCard key={`new-${p.id}`} p={p}/>)}</div></section><RecentlyViewed products={products}/><section className="section socialStrip socialGallery"><div className="socialGalleryCopy"><span className="eyebrow">Instagram</span><h2>Inspirações da Home.</h2><p>Uma seleção visual leve, sem incorporar um feed pesado.</p><a className="btn" href={s.instagram_url} target="_blank" rel="noreferrer"><Instagram size={16}/> @homeinterioresoficial</a></div><div className="socialGalleryGrid">{products.slice(0,3).map(p=><a href={s.instagram_url} target="_blank" rel="noreferrer" key={`ig-${p.id}`} aria-label="Abrir Instagram"><img loading="lazy" src={productImages(p)[0]} alt=""/></a>)}</div></section></Shell>}
function PageHero({kicker,title,text,image}){return <section className={`pageHero ${image?'withImage':''}`}><div><span className="eyebrow">{kicker}</span><h1>{title}</h1><p>{text}</p></div>{image&&<img src={image} alt=""/>}</section>}
function SkeletonGrid(){return <div className="productGrid catalogGrid">{Array.from({length:6}).map((_,i)=><div className="skeletonCard" key={i}><div/><span/><b/></div>)}</div>}
function Catalog(){const [params]=useSearchParams();const [products,setProducts]=useState([]),[q,setQ]=useState(''),[cat,setCat]=useState(params.get('categoria')||'Todos'),[loading,setLoading]=useState(true),[selected,setSelected]=useState(null);useEffect(()=>{listProducts().then(x=>{setProducts(x);setLoading(false)})},[]);const publicProducts=products.filter(p=>p.published!==false&&p.publication_status!=='draft');const cats=['Todos',...new Set(publicProducts.map(x=>x.category).filter(Boolean))];const nq=normalizeText(q);const filtered=useMemo(()=>publicProducts.filter(p=>(cat==='Todos'||p.category===cat)&&normalizeText(`${p.name} ${p.description} ${p.category} ${p.code}`).includes(nq)).sort((a,b)=>(Number(a.sort_order)||999)-(Number(b.sort_order)||999)),[publicProducts,q,cat]);return <Shell><Seo title="Catálogo" description="Explore o catálogo Home Interiores: sofás, mesas, poltronas, cadeiras, aparadores e decoração selecionada."/><section className="catalogIntro"><span className="eyebrow">Catálogo Home</span><h1>Encontre sua próxima peça.</h1></section><section className="section catalog"><div className="catalogTools stickyCatalogTools"><label className="searchBox"><Search size={18}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar sofá, mesa, código..." autoComplete="off"/>{q&&<button onClick={()=>setQ('')} aria-label="Limpar busca"><X size={16}/></button>}</label>{q&&<div className="instantSearch">{filtered.slice(0,4).map(p=><Link key={p.id} to={productPath(p)}><img src={productImages(p)[0]} alt=""/><span><b>{p.name}</b><small>{p.code} · {p.category}</small></span></Link>)}</div>}<div className="filterGroup"><span>Categoria</span><div className="chips">{cats.map(c=><button className={cat===c?'active':''} onClick={()=>setCat(c)} key={c}>{c}</button>)}</div></div></div>{loading?<SkeletonGrid/>:<><div className="catalogResultCount"><span>{filtered.length} peça(s)</span>{(cat!=='Todos'||q)&&<button onClick={()=>{setCat('Todos');setQ('')}}>Limpar filtros</button>}</div><div className="productGrid catalogGrid">{filtered.map(p=><ProductCard p={p} key={p.id} onOpen={setSelected}/>)}</div>{!filtered.length&&<div className="empty premiumEmpty"><Search size={28}/><h2>Nenhuma peça encontrada.</h2><p>Tente outro termo ou volte a visualizar toda a curadoria.</p><button className="btn" onClick={()=>{setCat('Todos');setQ('')}}>Ver todos os produtos</button></div>}</>}</section><ProductModal product={selected} products={products} onClose={()=>setSelected(null)}/></Shell>}

function About(){return <Shell><Seo title="A Home" description="Conheça a Home Interiores, sua curadoria, propósito e compromisso com design e excelência."/><PageHero kicker="A Home" title="Curadoria com identidade. Excelência em cada detalhe." text="A Home Interiores acredita que os melhores espaços nascem quando design e propósito caminham juntos." image={detailImg}/><section className="section values"><article><span className="eyebrow">Missão</span><h2>Transformar ambientes em experiências.</h2><p>Unindo design, curadoria e excelência para criar espaços que traduzam a essência de cada cliente.</p></article><article><span className="eyebrow">Visão</span><h2>Ser referência em mobiliário e interiores.</h2><p>Reconhecida pelo bom gosto, pela curadoria e pela excelência em cada detalhe.</p></article></section><section className="section cream"><span className="eyebrow">Valores</span><h2>Princípios que orientam cada escolha.</h2><div className="valueGrid">{[['Excelência','Qualidade em cada escolha.'],['Curadoria','Peças que unem estética, autenticidade e propósito.'],['Design','Beleza, funcionalidade e personalidade.'],['Atendimento','Encantar em cada experiência.'],['Ética','Relações construídas com confiança e transparência.'],['Inovação','Evoluir sem perder nossa essência.']].map(([a,b],i)=><article key={a}><span>0{i+1}</span><h3>{a}</h3><p>{b}</p></article>)}</div></section><section className="section essence"><span className="eyebrow">Essência Home</span><h2>Design que acolhe.<br/>Curadoria que inspira.<br/>Excelência que permanece.</h2></section></Shell>}
function Contact(){const s=useSettings();return <Shell><Seo title="Contato" description="Fale com a Home Interiores pelo WhatsApp ou Instagram e consulte peças, medidas, acabamentos e disponibilidade."/><PageHero kicker="Atendimento" title="Vamos criar algo que tenha a sua essência." text="Fale com a Home Interiores para conhecer peças, disponibilidade, acabamentos e possibilidades para o seu ambiente."/><section className="section contactGrid"><a href={waLink(s.whatsapp_general)} target="_blank" rel="noreferrer"><WhatsAppIcon size={24}/><span>WhatsApp</span><h3>Fale com nossa equipe</h3><p>Atendimento para produtos, curadoria e informações.</p><ArrowUpRight/></a><a href={s.instagram_url} target="_blank" rel="noreferrer"><Instagram/><span>Instagram</span><h3>@homeinterioresoficial</h3><p>Acompanhe novidades, ambientes e nossa curadoria.</p><ArrowUpRight/></a><div><MapPin/><span>Localização</span><h3>{s.location}</h3><p>Atendimento da Home Interiores em Sete Lagoas, Minas Gerais.</p></div></section></Shell>}

const blank={name:'',slug:'',code:'',category:'',description:'',price:'',old_price:'',status:'Disponível',published:true,publication_status:'published',sort_order:100,related_ids:[],image_url:'',image_urls:[],seller_name:'Equipe Home Interiores',seller_whatsapp:defaultSettings.whatsapp_general,featured:false};
const blankCategory={id:'',name:''};

function Admin(){
 const [authed,setAuthed]=useState(false),[password,setPassword]=useState(''),[tab,setTab]=useState('products'),[products,setProducts]=useState([]),[categories,setCategories]=useState([]),[form,setForm]=useState(blank),[categoryForm,setCategoryForm]=useState(blankCategory),[settings,setSettings]=useState(defaultSettings),[busy,setBusy]=useState(false),[msg,setMsg]=useState('');
 useEffect(()=>{let alive=true;(async()=>{if(await checkAdminSession()){if(!alive)return;setAuthed(true);await loadAll()}})();return()=>{alive=false}},[]);
 async function loadAll(){const [p,s,c]=await Promise.all([listProducts(),getSiteSettings(),listCategories()]);setProducts(p);setSettings(s);setCategories(c)}
 async function login(e){e.preventDefault();setMsg('');setBusy(true);try{await adminLogin(password);setAuthed(true);await loadAll()}catch(err){setMsg(err.message||'Senha inválida.')}finally{setBusy(false)}}
 async function logout(){await adminLogout();setAuthed(false);setPassword('')}
 async function submitProduct(e){e.preventDefault();setMsg('');if(!form.id&&products.length>=MAX_PRODUCTS){setMsg(`Limite máximo de ${MAX_PRODUCTS} produtos atingido. Exclua um produto para cadastrar outro.`);return;}setBusy(true);try{const maxCode=products.reduce((m,p)=>Math.max(m,Number(String(p.code||'').match(/(\d+)/)?.[1]||0)),0);const code=form.code||productCode(maxCode);const payload={...form,code,slug:form.slug||`${slugify(form.name)}-${code.toLowerCase()}`};await saveProduct(payload);setForm({...blank,category:categories[0]?.name||''});setProducts(await listProducts());setMsg('Produto salvo com sucesso.')}catch(err){setMsg(`Erro: ${err.message}`)}finally{setBusy(false)}}
 function newProduct(){if(products.length>=MAX_PRODUCTS){setMsg(`Você já utiliza ${products.length} de ${MAX_PRODUCTS} produtos. Exclua um produto para liberar uma nova vaga.`);return;}setMsg('');setForm({...blank,category:categories[0]?.name||''});window.scrollTo({top:0,behavior:'smooth'})}
 async function remove(id){if(!confirm('Remover este produto?'))return;try{await deleteProduct(id);setProducts(await listProducts())}catch(err){setMsg(`Erro: ${err.message}`)}}
 async function productFiles(e){const files=Array.from(e.target.files||[]);if(!files.length)return;const tooSmall=[];for(const f of files){const dim=await new Promise(resolve=>{const img=new Image();img.onload=()=>resolve([img.naturalWidth,img.naturalHeight]);img.onerror=()=>resolve([0,0]);img.src=URL.createObjectURL(f)});if(Math.min(...dim.filter(Boolean))<700)tooSmall.push(f.name)}if(tooSmall.length&&!confirm(`Algumas imagens têm resolução baixa: ${tooSmall.join(', ')}. Deseja enviar mesmo assim?`)){e.target.value='';return;}setBusy(true);try{const urls=[];for(const f of files)urls.push(await uploadImage(f));setForm(curr=>{const existing=productImages(curr).filter(u=>u!==seedProducts[0].image_url);const image_urls=[...new Set([...existing,...urls])];return {...curr,image_url:image_urls[0]||'',image_urls}});e.target.value=''}catch(err){setMsg(`Erro no upload: ${err.message}`)}finally{setBusy(false)}}
 function removeFormImage(index){setForm(f=>{const imgs=productImages(f).filter(u=>u!==seedProducts[0].image_url);const next=imgs.filter((_,i)=>i!==index);return {...f,image_url:next[0]||'',image_urls:next}})}
 function setCover(index){setForm(f=>{const imgs=productImages(f).filter(u=>u!==seedProducts[0].image_url);const chosen=imgs[index];const next=[chosen,...imgs.filter((_,i)=>i!==index)];return {...f,image_url:next[0]||'',image_urls:next}})}
 function moveFormImage(index,dir){setForm(f=>{const imgs=productImages(f).filter(u=>u!==seedProducts[0].image_url);const target=index+dir;if(target<0||target>=imgs.length)return f;[imgs[index],imgs[target]]=[imgs[target],imgs[index]];return {...f,image_url:imgs[0]||'',image_urls:imgs}})}
 async function settingImage(e,key){const file=e.target.files?.[0];if(!file)return;setBusy(true);try{const url=await uploadImage(file);setSettings(s=>({...s,[key]:url}));e.target.value=''}catch(err){setMsg(`Erro no upload: ${err.message}`)}finally{setBusy(false)}}
 async function submitSettings(e){e.preventDefault();setBusy(true);setMsg('');try{const saved=await saveSiteSettings(settings);setSettings(saved);setMsg('Configurações salvas com sucesso.')}catch(err){setMsg(`Erro: ${err.message}`)}finally{setBusy(false)}}
 async function submitCategory(e){e.preventDefault();setBusy(true);setMsg('');try{await saveCategory(categoryForm);setCategoryForm(blankCategory);const [c,p]=await Promise.all([listCategories(),listProducts()]);setCategories(c);setProducts(p);setMsg(categoryForm.id?'Categoria atualizada com sucesso.':'Categoria criada com sucesso.')}catch(err){setMsg(`Erro: ${err.message}`)}finally{setBusy(false)}}
 async function removeCategory(id){if(!confirm('Remover esta categoria?'))return;setBusy(true);setMsg('');try{await deleteCategory(id);setCategories(await listCategories());setMsg('Categoria removida.')}catch(err){setMsg(`Erro: ${err.message}`)}finally{setBusy(false)}}
 function switchTab(next){setTab(next);setMsg('');if(next==='products'&&!form.category&&categories[0])setForm(f=>({...f,category:categories[0].name}))}
 if(!authed)return <><header className="adminLoginHeader"><Link to="/"><BrandLogo/></Link></header><main className="adminLogin"><form onSubmit={login}><span className="eyebrow">Área restrita</span><h1>Painel Home</h1><p>Digite a senha para acessar.</p><input autoFocus type="password" required placeholder="Senha" value={password} onChange={e=>setPassword(e.target.value)}/><button className="btn" type="submit" disabled={busy}>{busy?<Loader2 className="spin" size={17}/>:null} Entrar <ArrowRight size={16}/></button>{msg&&<small className="formMsg">{msg}</small>}</form></main></>;
 return <div className="adminPage"><aside className="adminSide"><Link className="adminLogoLink" to="/"><BrandLogo admin/></Link><nav><button className={tab==='products'?'active':''} onClick={()=>switchTab('products')}><Package size={17}/> Produtos</button><button className={tab==='categories'?'active':''} onClick={()=>switchTab('categories')}><Tags size={17}/> Categorias</button><button className={tab==='settings'?'active':''} onClick={()=>switchTab('settings')}><SlidersHorizontal size={17}/> Configurações</button><Link to="/" target="_blank"><Eye size={17}/> Ver site</Link></nav><button className="logout" onClick={logout}><LogOut size={17}/> Sair</button></aside><main className="adminMain">
 {tab==='products'&&<><div className="adminTop"><div><span className="eyebrow">Catálogo</span><h1>Produtos</h1><p>Gerencie catálogo, fotos e contato de cada peça.</p></div><button className="btn" onClick={newProduct} disabled={products.length>=MAX_PRODUCTS} title={products.length>=MAX_PRODUCTS?`Limite de ${MAX_PRODUCTS} produtos atingido`:undefined}><Plus size={17}/> {products.length>=MAX_PRODUCTS?'Limite atingido':'Novo produto'}</button></div><div className="adminLayout"><form className="productForm" onSubmit={submitProduct}><h2>{form.id?'Editar produto':'Novo produto'}</h2><div className="formSteps"><span><b>1</b> Informações</span><span><b>2</b> Comercial</span><span><b>3</b> Fotos</span><span><b>4</b> Publicação</span></div><label>Nome<input required value={form.name} onChange={e=>{const name=e.target.value;const suggested=inferCategory(name,categories);setForm(curr=>({...curr,name,category:(!curr.id&&suggested)?suggested:curr.category}))}}/><small className="fieldHelp">Ao reconhecer o tipo de peça, o sistema sugere a categoria automaticamente.</small></label><button type="button" className="smartFillBtn" onClick={()=>setForm(curr=>smartProductDraft(curr.name,categories,curr))}>Preencher com inteligência</button><label>Categoria<select required value={form.category||''} onChange={e=>setForm({...form,category:e.target.value})}><option value="" disabled>Selecione uma categoria</option>{categories.map(c=><option key={c.id} value={c.name}>{c.name}</option>)}</select><small className="fieldHelp">As categorias são gerenciadas na aba Categorias.</small></label><label>Descrição<textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><h3 className="formSectionLabel">2. Comercial</h3><div className="formRow"><label>Preço atual <small>(opcional)</small><input value={form.price||''} onChange={e=>setForm({...form,price:e.target.value})} placeholder="Ex.: R$ 5.990"/></label><label>Preço anterior <small>(promoção)</small><input value={form.old_price||''} onChange={e=>setForm({...form,old_price:e.target.value})} placeholder="Ex.: R$ 6.990"/></label></div><div className="formRow"><label>Status<select value={form.status||'Disponível'} onChange={e=>setForm({...form,status:e.target.value})}><option>Disponível</option><option>Sob encomenda</option><option>Última unidade</option><option>Novidade</option></select></label><label>Ordem<input type="number" value={form.sort_order??100} onChange={e=>setForm({...form,sort_order:Number(e.target.value)})}/></label></div><label>Produtos relacionados<select multiple value={form.related_ids||[]} onChange={e=>setForm({...form,related_ids:Array.from(e.target.selectedOptions).map(o=>o.value)})}>{products.filter(x=>x.id!==form.id).map(x=><option key={x.id} value={x.id}>{x.code} · {x.name}</option>)}</select><small className="fieldHelp">Ctrl/Cmd + clique para escolher mais de um.</small></label><label>Vendedor<input required value={form.seller_name||''} onChange={e=>setForm({...form,seller_name:e.target.value})}/></label><label>WhatsApp do vendedor<input required value={form.seller_whatsapp||''} onChange={e=>setForm({...form,seller_whatsapp:e.target.value})}/></label><h3 className="formSectionLabel">3. Fotos</h3><label>Imagens do produto <small>(selecione várias)</small><span className="uploadBtn"><Upload size={16}/> Adicionar imagens<input type="file" accept="image/*" multiple onChange={productFiles}/></span></label>{productImages(form).filter(u=>u!==seedProducts[0].image_url).length>0&&<div className="formGallery">{productImages(form).filter(u=>u!==seedProducts[0].image_url).map((url,i)=><div className="formGalleryItem" key={url+i}><img src={url} alt=""/><button className="removePhoto" type="button" onClick={()=>removeFormImage(i)}><X size={15}/></button>{i===0?<span>Capa</span>:<button className="makeCover" type="button" onClick={()=>setCover(i)}>Definir capa</button>}<div className="photoOrder"><button type="button" disabled={i===0} onClick={()=>moveFormImage(i,-1)}><ChevronLeft size={14}/></button><button type="button" disabled={i===productImages(form).filter(u=>u!==seedProducts[0].image_url).length-1} onClick={()=>moveFormImage(i,1)}><ChevronRight size={14}/></button></div></div>)}</div>}<h3 className="formSectionLabel">4. Publicação</h3><label className="check"><input type="checkbox" checked={form.published!==false} onChange={e=>setForm({...form,published:e.target.checked,publication_status:e.target.checked?'published':'draft'})}/><span><Check size={14}/></span> Publicado no catálogo</label><label className="check"><input type="checkbox" checked={!!form.featured} onChange={e=>setForm({...form,featured:e.target.checked})}/><span><Check size={14}/></span> Mostrar como destaque</label><button className="btn" disabled={busy||(!form.id&&products.length>=MAX_PRODUCTS)}>{busy?<Loader2 className="spin" size={17}/>:<Check size={17}/>} {(!form.id&&products.length>=MAX_PRODUCTS)?'Limite de 30 produtos atingido':'Salvar produto'}</button>{msg&&<small className="formMsg">{msg}</small>}</form><section className="adminProducts"><div className={`adminCount productLimitCount ${products.length>=MAX_PRODUCTS?'full':''}`}><span>{products.length} de {MAX_PRODUCTS} produtos utilizados</span><span>{Math.max(0,MAX_PRODUCTS-products.length)} vaga(s) disponível(is)</span></div>{products.map(p=><article key={p.id}><img src={productImages(p)[0]} alt={p.name}/><div><span>{p.category}</span><h3>{p.name}</h3><small>{p.seller_name}</small></div><div className="rowActions"><Link to={productPath(p)} target="_blank" title="Pré-visualizar"><Eye size={17}/></Link><button title="Duplicar" onClick={()=>{const clone={...p,id:'',name:`${p.name} (cópia)`,code:'',slug:'',featured:false,published:false,publication_status:'draft'};setForm(clone);window.scrollTo({top:0,behavior:'smooth'})}}><Copy size={17}/></button><button onClick={()=>{setForm({...p,image_urls:productImages(p).filter(Boolean)});window.scrollTo({top:0,behavior:'smooth'})}}><Pencil size={17}/></button><button onClick={()=>remove(p.id)}><Trash2 size={17}/></button></div></article>)}</section></div></>}
 {tab==='categories'&&<><div className="adminTop"><div><span className="eyebrow">Organização do catálogo</span><h1>Categorias</h1><p>Crie e edite as categorias que aparecem no cadastro dos produtos.</p></div><button className="btn" onClick={()=>{setCategoryForm(blankCategory);setMsg('')}}><Plus size={17}/> Nova categoria</button></div><div className="categoryAdminLayout"><form className="productForm categoryForm" onSubmit={submitCategory}><h2>{categoryForm.id?'Editar categoria':'Nova categoria'}</h2><label>Nome da categoria<input autoComplete="off" required value={categoryForm.name} onChange={e=>setCategoryForm({...categoryForm,name:e.target.value})} placeholder="Ex.: Mesas laterais"/></label><label>Endereço no rodapé<input value={settings.footer_address||''} onChange={e=>setSettings({...settings,footer_address:e.target.value})}/></label><label>Horário de atendimento<input value={settings.business_hours||''} onChange={e=>setSettings({...settings,business_hours:e.target.value})}/></label><label>E-mail de privacidade<input value={settings.privacy_email||''} onChange={e=>setSettings({...settings,privacy_email:e.target.value})}/></label><button className="btn" disabled={busy}>{busy?<Loader2 className="spin" size={17}/>:<Check size={17}/>} {categoryForm.id?'Salvar alteração':'Criar categoria'}</button>{categoryForm.id&&<button type="button" className="btn outline categoryCancel" onClick={()=>setCategoryForm(blankCategory)}>Cancelar edição</button>}{msg&&<small className="formMsg">{msg}</small>}</form><section className="categoryList"><div className="adminCount"><span>{categories.length} categorias cadastradas</span></div>{categories.map(c=>{const count=products.filter(p=>p.category===c.name).length;return <article key={c.id}><div><span>Categoria</span><h3>{c.name}</h3><small>{count} produto(s) nesta categoria</small></div><div className="rowActions"><button onClick={()=>{setCategoryForm({id:c.id,name:c.name});window.scrollTo({top:0,behavior:'smooth'})}}><Pencil size={17}/></button><button onClick={()=>removeCategory(c.id)} disabled={count>0} title={count>0?'Troque a categoria dos produtos antes de excluir.':'Excluir categoria'}><Trash2 size={17}/></button></div></article>})}</section></div></>}
 {tab==='settings'&&<><div className="adminTop"><div><span className="eyebrow">Site</span><h1>Configurações</h1><p>Troque o hero, textos e contatos sem alterar o código.</p></div></div><div className="settingsLayout"><form className="productForm settingsForm" onSubmit={submitSettings}><h2>Conteúdo da Home</h2><label>Foto do hero<div className="settingsImagePreview"><img src={settings.hero_image_url} alt="Hero atual"/></div><span className="uploadBtn"><ImageIcon size={16}/> Trocar foto do hero<input type="file" accept="image/*" onChange={e=>settingImage(e,'hero_image_url')}/></span></label><label>Texto pequeno do hero<input value={settings.hero_kicker||''} onChange={e=>setSettings({...settings,hero_kicker:e.target.value})}/></label><label>Título principal<input value={settings.hero_title||''} onChange={e=>setSettings({...settings,hero_title:e.target.value})}/></label><label>Subtítulo<textarea value={settings.hero_subtitle||''} onChange={e=>setSettings({...settings,hero_subtitle:e.target.value})}/></label><label>Frase Essência Home<textarea value={settings.essence_text||''} onChange={e=>setSettings({...settings,essence_text:e.target.value})}/></label><label>Imagem institucional<div className="settingsImagePreview small"><img src={settings.institutional_image_url} alt="Imagem institucional"/></div><span className="uploadBtn"><ImageIcon size={16}/> Trocar imagem<input type="file" accept="image/*" onChange={e=>settingImage(e,'institutional_image_url')}/></span></label><h2 className="settingsSectionTitle">Faixa promocional</h2><label className="promoToggle"><input type="checkbox" checked={settings.promo_enabled!==false} onChange={e=>setSettings({...settings,promo_enabled:e.target.checked})}/><span>Exibir faixa de ofertas no topo do site</span></label><div className="formRow"><label>Início da campanha<input type="datetime-local" value={settings.promo_start_at||''} onChange={e=>setSettings({...settings,promo_start_at:e.target.value})}/></label><label>Fim da campanha<input type="datetime-local" value={settings.promo_end_at||''} onChange={e=>setSettings({...settings,promo_end_at:e.target.value})}/></label></div><div className="promoSettingsList">{(settings.promo_messages||defaultSettings.promo_messages).slice(0,5).map((item,i)=><label key={i}>Chamada {i+1}<input value={item||''} onChange={e=>{const next=[...(settings.promo_messages||defaultSettings.promo_messages)];next[i]=e.target.value;setSettings({...settings,promo_messages:next})}} maxLength={80}/></label>)}</div><h2 className="settingsSectionTitle">SEO e compartilhamento</h2><label>Imagem Open Graph <small>(link)</small><input value={settings.og_image_url||''} onChange={e=>setSettings({...settings,og_image_url:e.target.value})} placeholder="Pode usar a imagem do hero"/></label><h2 className="settingsSectionTitle">Contato</h2><label>Instagram<input value={settings.instagram_url||''} onChange={e=>setSettings({...settings,instagram_url:e.target.value})}/></label><label>WhatsApp geral<input value={settings.whatsapp_general||''} onChange={e=>setSettings({...settings,whatsapp_general:e.target.value})}/></label><label>Endereço/Localização<input value={settings.location||''} onChange={e=>setSettings({...settings,location:e.target.value})}/></label><label>Endereço no rodapé<input value={settings.footer_address||''} onChange={e=>setSettings({...settings,footer_address:e.target.value})}/></label><label>Horário de atendimento<input value={settings.business_hours||''} onChange={e=>setSettings({...settings,business_hours:e.target.value})}/></label><label>E-mail de privacidade<input value={settings.privacy_email||''} onChange={e=>setSettings({...settings,privacy_email:e.target.value})}/></label><button className="btn" disabled={busy}>{busy?<Loader2 className="spin" size={17}/>:<Check size={17}/>} Salvar configurações</button>{msg&&<small className="formMsg">{msg}</small>}</form><section className="sitePreview"><div className="previewLabel"><Eye size={16}/> Prévia do hero</div><div className="previewHero"><img src={settings.hero_image_url} alt="Prévia"/><div className="overlay"/><div><span>{settings.hero_kicker}</span><h2>{settings.hero_title}</h2><p>{settings.hero_subtitle}</p><small>{settings.essence_text}</small></div></div><p className="previewNote">A prévia atualiza enquanto você edita. Clique em “Salvar configurações” para publicar.</p></section></div></>}
 </main></div>
}


function ProductPage(){const {slug}=useParams();const [products,setProducts]=useState([]),[loading,setLoading]=useState(true),[active,setActive]=useState(0),[fullscreen,setFullscreen]=useState(false);const fav=useFavorites();useEffect(()=>{listProducts().then(x=>{setProducts(x);setLoading(false)})},[]);const p=products.find(x=>(x.slug||'')===slug || productPath(x)===`/produto/${slug}`);useEffect(()=>{if(p?.id)saveRecentProduct(p.id)},[p?.id]);useEffect(()=>{if(!p)return;const imgs=productImages(p);if(imgs.length>1){const img=new Image();img.src=imgs[(active+1)%imgs.length]}},[p?.id,active]);if(loading)return <Shell><div className="pageLoading"><Loader2 className="spin"/></div></Shell>;if(!p||p.published===false)return <NotFound/>;const imgs=productImages(p);const related=(Array.isArray(p.related_ids)&&p.related_ids.length?products.filter(x=>p.related_ids.includes(x.id)):products.filter(x=>x.category===p.category&&x.id!==p.id)).slice(0,3);const share=async()=>{const data={title:p.name,text:`${p.name} — Home Interiores`,url:location.href};if(navigator.share)await navigator.share(data).catch(()=>{});else{await navigator.clipboard?.writeText(location.href);notify('Link do produto copiado.')}};return <Shell><Seo title={p.name} description={p.description||`Conheça ${p.name} na Home Interiores.`} image={imgs[0]}/><section className="productPage"><div className="productPageGallery"><div className="productPageMain"><img src={imgs[active]} alt={`${p.name} - foto ${active+1}`} onError={e=>{e.currentTarget.onerror=null;e.currentTarget.src=designFallback}}/><span>{active+1} / {imgs.length}</span><button className="fullscreenGalleryBtn" onClick={()=>setFullscreen(true)} aria-label="Ampliar imagem"><Maximize2 size={18}/></button></div>{imgs.length>1&&<div className="productPageThumbs">{imgs.map((u,i)=><button className={i===active?'active':''} onClick={()=>setActive(i)} key={u+i}><img src={u} alt=""/></button>)}</div>}</div><div className="productPageInfo"><span className="eyebrow">{p.category} · {p.code}</span><h1>{p.name}</h1><div className="productStatus">{p.status||'Disponível'}</div><p>{p.description}</p><div className="pagePrice">{p.old_price&&<del>{p.old_price}</del>}{p.price?<strong>{p.price}</strong>:<strong>Valor sob consulta</strong>}</div><div className="productPageActions"><a className="btn" href={waLink(p.seller_whatsapp,p.name,p.code)} target="_blank" rel="noreferrer" onClick={()=>trackEvent('whatsapp_product',{product:p.code,page:'detail'})}><WhatsAppIcon size={17}/> Consultar no WhatsApp</a><button className={`btn outline ${fav.has(p.id)?'active':''}`} onClick={()=>{fav.toggle(p.id);notify(fav.has(p.id)?'Produto removido dos favoritos.':'Produto salvo nos favoritos.')}}><Heart size={17} fill={fav.has(p.id)?'currentColor':'none'}/> {fav.has(p.id)?'Salvo':'Favoritar'}</button><button className="iconAction" onClick={share} aria-label="Compartilhar"><Share2 size={18}/></button></div><a className="showroomLink" href={waLink(p.seller_whatsapp,`confirmar se ${p.name} está disponível no showroom`,p.code)} target="_blank" rel="noreferrer">Ver no showroom <ArrowUpRight size={15}/></a></div></section>{fullscreen&&<div className="fullscreenGallery" role="dialog" aria-modal="true"><button className="fullscreenClose" onClick={()=>setFullscreen(false)} aria-label="Fechar"><X size={24}/></button>{imgs.length>1&&<button className="fullscreenPrev" onClick={()=>setActive(i=>(i-1+imgs.length)%imgs.length)} aria-label="Anterior"><ChevronLeft size={28}/></button>}<img src={imgs[active]} alt={`${p.name} ampliado`}/>{imgs.length>1&&<button className="fullscreenNext" onClick={()=>setActive(i=>(i+1)%imgs.length)} aria-label="Próxima"><ChevronRight size={28}/></button>}<span className="fullscreenCount">{active+1} / {imgs.length}</span></div>}{related.length>0&&<section className="section"><div className="sectionHead compactHead"><div><span className="eyebrow">Combine com</span><h2>Peças relacionadas.</h2></div></div><div className="productGrid">{related.map(x=><ProductCard key={x.id} p={x}/>)}</div></section>}<RecentlyViewed products={products} title="Você também viu"/></Shell>}
function FavoritesPage(){const [products,setProducts]=useState([]);const fav=useFavorites();useEffect(()=>{listProducts().then(setProducts)},[]);const items=products.filter(p=>fav.ids.includes(p.id)&&p.published!==false);const settings=useSettings();const quote=()=>{const lines=items.map(p=>`• ${p.name} (${p.code})`).join('\n');window.open(`https://wa.me/${String(settings.whatsapp_general).replace(/\D/g,'')}?text=${encodeURIComponent(`Olá! Montei esta seleção no site da Home Interiores e gostaria de um orçamento:\n${lines}`)}`,'_blank')};return <Shell><Seo title="Favoritos" description="Sua seleção de produtos favoritos da Home Interiores." noindex/><section className="catalogIntro"><span className="eyebrow">Sua seleção</span><h1>Favoritos.</h1><p>Salve peças e envie todas de uma vez para o atendimento.</p></section><section className="section">{items.length?<><div className="favoritesToolbar"><span>{items.length} peça(s) selecionada(s)</span><button className="btn" onClick={quote}><WhatsAppIcon size={16}/> Solicitar orçamento da seleção</button></div><div className="productGrid">{items.map(p=><ProductCard key={p.id} p={p}/>)}</div></>:<div className="empty favoritesEmpty"><Heart size={28}/><h2>Nenhuma peça salva ainda.</h2><p>Toque no coração dos produtos para montar sua seleção.</p><Link className="btn" to="/catalogo">Abrir catálogo</Link></div>}</section></Shell>}
function LegalPage({type}){const privacy=type==='privacy';const s=useSettings();return <Shell><Seo title={privacy?'Política de Privacidade':'Termos de Uso'} description={`${privacy?'Política de Privacidade':'Termos de Uso'} da Home Interiores.`}/><section className="legalPage"><span className="eyebrow">Home Interiores</span><h1>{privacy?'Política de Privacidade':'Termos de Uso'}</h1>{privacy?<><p>Esta página explica, de forma objetiva, como dados informados voluntariamente no site podem ser tratados.</p><h2>Dados e contato</h2><p>O catálogo pode direcionar você ao WhatsApp ou Instagram. Ao usar esses serviços, o tratamento de dados também segue as políticas das respectivas plataformas.</p><h2>Cookies e armazenamento local</h2><p>O site usa armazenamento local para recursos essenciais, como favoritos, produtos vistos recentemente e suas preferências de privacidade. Cookies ou tecnologias de análise e marketing só devem ser ativados conforme a escolha feita no painel de preferências.</p><h2>Suas preferências</h2><p>Você pode revisar ou alterar as preferências de cookies a qualquer momento pelo link disponível no rodapé do site.</p><h2>Solicitações</h2><p>Para dúvidas sobre privacidade, entre em contato pelo canal oficial da Home Interiores{s.privacy_email?` ou pelo e-mail ${s.privacy_email}`:''}.</p></>:<><p>Ao navegar neste site, você concorda com o uso do catálogo para consulta de produtos e contato comercial.</p><h2>Informações comerciais</h2><p>Preços, disponibilidade, frete, acabamentos e condições podem mudar e devem ser confirmados diretamente com a equipe antes da compra.</p><h2>Imagens e conteúdo</h2><p>As imagens e descrições têm caráter informativo. Cores e proporções podem variar conforme tela, iluminação e acabamento selecionado.</p><h2>Links externos</h2><p>O site pode direcionar para WhatsApp e Instagram. Esses serviços possuem termos próprios.</p></>}</section></Shell>}
function NotFound(){return <Shell><Seo title="Página não encontrada" description="A página que você tentou acessar não foi encontrada." noindex/><section className="notFound"><span>404</span><h1>Esta peça saiu de cena.</h1><p>A página não existe ou não está mais disponível. O catálogo continua por aqui.</p><div><Link className="btn" to="/catalogo">Ver catálogo</Link><Link className="btn outline" to="/">Voltar à Home</Link></div></section></Shell>}

function App(){return <BrowserRouter><Routes><Route path="/" element={<Home/>}/><Route path="/catalogo" element={<Catalog/>}/><Route path="/produto/:slug" element={<ProductPage/>}/><Route path="/favoritos" element={<FavoritesPage/>}/><Route path="/sobre" element={<About/>}/><Route path="/contato" element={<Contact/>}/><Route path="/privacidade" element={<LegalPage type="privacy"/>}/><Route path="/termos" element={<LegalPage type="terms"/>}/><Route path="/admin" element={<Admin/>}/><Route path="*" element={<NotFound/>}/></Routes></BrowserRouter>}
createRoot(document.getElementById('root')).render(<App/>);
